import{_ as n,C as o,c as a,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Blanket orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/orders/blanket-orders.md","filePath":"master/supply-chain/purchase/orders/blanket-orders.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/purchase/orders/blanket-orders.md"};function d(g,e,h,u,c,m){const r=o("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="blanket-orders" tabindex="-1">Blanket orders <a class="header-anchor" href="#blanket-orders" aria-label="Permalink to &quot;Blanket orders&quot;">​</a></h1><p>A blanket order is a long term deal with one vendor. You agree on products, a total quantity and a price for a period. Each RFQ you raise against it uses that price and counts against the total quantity.</p><blockquote><p><strong>In simple words:</strong> A blanket order is a promise to buy a set quantity at a fixed price over time. Orders draw from it until it is used up.</p></blockquote><p>Open <code>Purchase → Orders → Purchase Agreements</code> and click the <strong>Blanket Orders</strong> tab.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The menu is hidden until you turn it on. Go to <code>Purchase → Settings → Manage Orders</code> and switch on <strong>Purchase Agreements</strong>. The helper text reads &quot;Manage blanket orders and purchase templates&quot;. The same page is at <code>Settings → Settings → Purchase</code>. See <a href="./../get-started/purchase-settings.html">Purchase settings</a>.</p><h2 id="blanket-order-or-template" tabindex="-1">Blanket order or template <a class="header-anchor" href="#blanket-order-or-template" aria-label="Permalink to &quot;Blanket order or template&quot;">​</a></h2><p>Both share one form and one list. Choose <strong>Blanket Order</strong> in <strong>Agreement Type</strong> when you promise a total quantity over a period. Choose <strong>Purchase Template</strong> when you only want a ready-made set of lines. See <a href="./purchase-templates.html">Purchase templates</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows these columns: <strong>Agreement</strong>, <strong>Vendor</strong>, <strong>Agreement Type</strong>, <strong>Buyer</strong>, <strong>Company</strong>, <strong>Valid From</strong>, <strong>Valid Until</strong>, <strong>Reference</strong> and <strong>Status</strong>.</p>',10)),s(r,{src:"/images1/purchase/agr_list.png",alt:"Purchase Agreements list with one confirmed blanket order for FreshFoods Wholesale"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Tab</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>All agreements</td></tr><tr><td><strong>My Agreements</strong></td><td>Agreements where you are the buyer</td></tr><tr><td><strong>Blanket Orders</strong></td><td>Only blanket orders</td></tr><tr><td><strong>Purchase Templates</strong></td><td>Only templates</td></tr><tr><td><strong>Draft</strong></td><td>Agreements not yet confirmed</td></tr><tr><td><strong>Done</strong></td><td>Closed agreements</td></tr><tr><td><strong>Archived</strong></td><td>Archived agreements</td></tr></tbody></table><p>Use <strong>Group by</strong> with <strong>Vendor</strong>, <strong>State</strong>, <strong>Agreement Type</strong>, <strong>Created At</strong> or <strong>Updated At</strong>.</p><h2 id="create-a-blanket-order" tabindex="-1">Create a blanket order <a class="header-anchor" href="#create-a-blanket-order" aria-label="Permalink to &quot;Create a blanket order&quot;">​</a></h2><p>Example: FreshFoods Wholesale agrees to sell you 100 <strong>SSD 512GB</strong> at 3,200 each for the year.</p><ol><li>Click <strong>New Purchase Agreement</strong>.</li></ol>',5)),s(r,{src:"/images1/purchase/agr_new_button.png",alt:"Purchase Agreements list with the New Purchase Agreement button highlighted"}),e[2]||(e[2]=t('<ol start="2"><li>Fill in the top section.</li></ol><ul><li><strong><em>Vendor:</em></strong> Required. The supplier who gave the offer.</li><li><strong><em>Buyer:</em></strong> The user in charge of the deal.</li><li><strong><em>Agreement Type:</em></strong> Required. Keep <strong>Blanket Order</strong>.</li><li><strong><em>Currency:</em></strong> Required. Starts with your company currency.</li><li><strong><em>Valid From</em></strong> and <strong><em>Valid Until</em>:</strong> Required for a blanket order. Dates cannot be in the past.</li><li><strong><em>Reference:</em></strong> Your own or the vendor&#39;s reference.</li><li><strong><em>Company:</em></strong> Required. Starts with your current company.</li></ul>',2)),s(r,{src:"/images1/purchase/agr_form_general.png",alt:"New blanket order for FreshFoods Wholesale with type, currency, dates and reference filled in"}),e[3]||(e[3]=t('<ol start="3"><li>On the <strong>Products</strong> tab, add a line for each product.</li></ol><ul><li><strong><em>Product:</em></strong> Required. Goods products only.</li><li><strong><em>Quantity:</em></strong> Required. The total you commit to.</li><li><strong><em>Ordered:</em></strong> Read only. Shows how much is already ordered.</li><li><strong><em>Unit of Measure:</em></strong> Shown only when <strong>Unit of Measure</strong> is on in <strong>Manage Products</strong>.</li><li><strong><em>Unit Price:</em></strong> Required. The agreed price.</li></ul>',2)),s(r,{src:"/images1/purchase/agr_form_lines.png",alt:"Products tab with SSD 512GB, quantity 100 and unit price 3200"}),e[4]||(e[4]=t(`<ol start="4"><li>Use the <strong>Terms and Conditions</strong> tab for notes the vendor should see.</li><li>Click <strong>Create</strong>. The agreement starts as <strong>Draft</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If this vendor already has a confirmed agreement that is not closed or canceled, a window asks <strong>Similar confirmed agreement exists</strong>. Click to continue only if you really want a second one.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>The state bar shows <strong>Draft</strong>, <strong>Confirmed</strong>, <strong>Closed</strong> and <strong>Canceled</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draft  &gt;  Confirmed  &gt;  Closed</span></span>
<span class="line"><span>   \\         \\</span></span>
<span class="line"><span>    +---------+---&gt;  Canceled</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Confirm</strong></td><td>Moves Draft to Confirmed. It needs at least one line.</td></tr><tr><td><strong>Close</strong></td><td>Moves Confirmed to Closed.</td></tr><tr><td><strong>Cancel</strong></td><td>Cancels the agreement. Hidden once closed or canceled.</td></tr><tr><td><strong>Print</strong></td><td>Downloads a PDF of the agreement.</td></tr><tr><td><strong>Delete</strong></td><td>Removes the agreement.</td></tr></tbody></table>`,6)),s(r,{src:"/images1/purchase/agr_confirmed.png",alt:"Confirmed purchase agreement with Close, Cancel and Print buttons in the header"}),e[5]||(e[5]=t('<p>Without a line, <strong>Confirm</strong> shows <strong>Unable to confirm purchase agreement</strong>. Add a product line first.</p><p><strong>Close</strong> is blocked while related RFQs are still open. The message reads &quot;You cannot close this purchase agreement because some related RFQs are not in Done or Canceled status.&quot; Finish or cancel those RFQs first.</p><p>After you confirm, vendor, buyer, type and company are locked.</p><h2 id="use-a-blanket-order-on-an-rfq" tabindex="-1">Use a blanket order on an RFQ <a class="header-anchor" href="#use-a-blanket-order-on-an-rfq" aria-label="Permalink to &quot;Use a blanket order on an RFQ&quot;">​</a></h2><p>The <strong>Agreement</strong> field shows on the RFQ form only when <strong>Purchase Agreements</strong> is on.</p><ol><li>Click <strong>New RFQ</strong> and pick the <strong>Vendor</strong>.</li><li>If the vendor has a confirmed agreement that is valid today, Aureus fills <strong>Agreement</strong>, the product lines and the <strong>Currency</strong> for you.</li><li>To choose another one, open the <strong>Agreement</strong> list. It offers confirmed agreements only.</li></ol>',6)),s(r,{src:"/images1/purchase/agr_rfq_filled.png",alt:"RFQ for FreshFoods Wholesale with Agreement filled and the SSD 512GB line copied in"}),e[6]||(e[6]=t('<p>Lines copied from an agreement keep the agreed unit price.</p><h2 id="quantity-limit" tabindex="-1">Quantity limit <a class="header-anchor" href="#quantity-limit" aria-label="Permalink to &quot;Quantity limit&quot;">​</a></h2><p>You cannot order more than the quantity left. If you try, Aureus shows <strong>Quantity Exceeds Blanket Order Limit</strong> and says how much is available. Lower the quantity or raise it on the agreement. The <strong>Ordered</strong> column on the agreement shows what is used.</p><h2 id="rfq-s-sub-page" tabindex="-1">RFQ&#39;s sub page <a class="header-anchor" href="#rfq-s-sub-page" aria-label="Permalink to &quot;RFQ&#39;s sub page&quot;">​</a></h2><p>Open an agreement and click <strong>RFQ&#39;s</strong> in the switcher. It lists the RFQs and orders made from this agreement. Check it before you click <strong>Close</strong>.</p>',5)),s(r,{src:"/images1/purchase/agr_rfqs.png",alt:"RFQ's sub page of the agreement listing the RFQs created from it"}),e[7]||(e[7]=t('<h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Agreements do not create stock or bills. They only feed order lines and cap blanket quantities. The order itself still follows the usual flow: confirm, receive, bill.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./purchase-templates.html">Purchase templates</a></li><li><a href="./quotations.html">Requests for quotation</a></li><li><a href="./purchase-orders.html">Purchase orders</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li><li><a href="./../get-started/purchase-settings.html">Purchase settings</a></li></ul>',4))])}const _=n(l,[["render",d]]);export{f as __pageData,_ as default};
